b:includable.script:
                    function action(type) {
                        const care = document.getElementById('care-selector').value;
                        const status = document.getElementById('status-msg');




const base = "Bertindaklah sebagai Pakar Perawatan Medis Profesional yang ahli dalam bidang " + care + ". " +
    "Setiap respons Anda harus bersifat analitis, berbasis bukti klinis terkini (evidence-based), dan disampaikan dengan nada empati serta profesional. " +
    "Untuk setiap permintaan, berikan: " +
    "1. Penjelasan mendalam dan komprehensif mengenai topik yang dibahas, " +
    "2. Panduan praktis langkah-demi-langkah (SOP), " +
    "3. Tabel atau poin-poin penting untuk kemudahan rujukan, " +
    "4. Bagian 'Bank Soal Evaluasi': Sediakan minimal 3 soal studi kasus (pilihan ganda/esai) yang mencakup berbagai skenario klinis, " +
    "5. Kunci jawaban beserta penjelasan rasional yang mendalam untuk setiap soal. " +
    "Tujuan saya adalah untuk menguasai topik ini secara paripurna. Pastikan seluruh output terstruktur rapi, logis, dan edukatif.";


                        let prompt = "";





if(type == "emergency") {
    prompt = base + 
        "Bertindaklah sebagai instruktur klinis ahli kegawatdaruratan paliatif. " +
        "1. Pilih secara acak 1 kondisi kegawatan yang sering terjadi dalam perawatan paliatif (contoh: perdarahan masif, kejang, dispnea berat, atau krisis nyeri). " +
        "2. Buatkan panduan penanganan cepat 'Life-Saving' dalam format poin-poin yang presisi, sistematis, dan mengikuti protokol medis terbaru. " +
        "3. Sertakan 'Red Flags' atau indikator yang memerlukan tindakan segera/rujukan. " +
        "4. Buatkan 3 Bank Soal (Studi Kasus Klinis) terkait kegawatdaruratan tersebut dan topik kegawatan paliatif lainnya. Setiap soal harus disertai 4 pilihan jawaban (A, B, C, D). " +
        "5. Berikan kunci jawaban beserta penjelasan rasional yang mendalam untuk setiap soal agar saya memahami dasar pengambilan keputusan klinisnya. " +
        "Sajikan seluruh materi dalam format modul yang terstruktur, profesional, dan mudah dipahami untuk keperluan pelatihan mandiri.";
}

else if(type == "assess") {
    prompt = base + 
        "Bertindaklah sebagai ahli klinis senior. Susun sebuah modul panduan komprehensif mengenai 'Alat Penilaian Klinis (Clinical Assessment Tools)' yang paling tepat dan esensial untuk pasien " + care + ". " +
        "Modul ini wajib mencakup: " +
        "1. Katalog Alat Penilaian: Berikan daftar alat penilaian (seperti skala nyeri, skala fungsional, skala depresi/kecemasan, dll) yang tervalidasi secara internasional untuk kondisi tersebut. " +
        "2. Analisis Kegunaan: Untuk setiap alat, jelaskan kapan, mengapa, dan bagaimana cara menggunakannya secara praktis di lingkungan klinis. " +
        "3. Interpretasi Hasil: Berikan panduan ringkas cara membaca skor atau hasil dari alat penilaian tersebut agar dapat membantu pengambilan keputusan klinis. " +
        "4. Bank Soal (3 Pertanyaan): Buatlah 3 soal studi kasus pilihan ganda yang menguji kemampuan klinis saya dalam memilih dan menginterpretasikan alat penilaian yang tepat untuk berbagai skenario pasien. " +
        "5. Kunci Jawaban & Rasional: Sertakan kunci jawaban beserta penjelasan rasional yang mendalam untuk setiap soal agar saya memahami logika di balik pemilihan alat tersebut. " +
        "Sajikan dalam format yang sangat terstruktur, profesional, menggunakan heading yang jelas, dan bahasa klinis yang presisi.";
}


else if(type == "pps") {
    prompt = base + 
        "Bertindaklah sebagai instruktur klinis ahli paliatif. Berikan pembahasan yang sangat komprehensif, paripurna, dan mendalam mengenai Palliative Performance Scale (PPS v2) dari Victoria Hospice. " +
        "Struktur output wajib mencakup: " +
        "1. Analisis Mendalam: Penjelasan rinci untuk setiap 11 level PPS (dari 100% hingga 0%), disertai dengan kriteria objektif pada setiap kategori (ambulasi, aktivitas, asupan, tingkat kesadaran). " +
        "2. Panduan Penilaian Praktikal: Tips klinis untuk menentukan skor secara akurat bagi pasien dengan kondisi fluktuatif. " +
        "3. Studi Kasus Komprehensif: Berikan 5 skenario klinis yang kompleks untuk melatih kemampuan scoring. " +
        "4. Bank Soal (3 Pertanyaan): Buatkan 3 soal studi kasus pilihan ganda yang bervariasi untuk menguji pemahaman tingkat tinggi mengenai PPS v2. " +
        "5. Kunci Jawaban & Rasional: Sertakan kunci jawaban beserta penjelasan medis yang rasional untuk setiap soal, sehingga saya memahami 'mengapa' skor tersebut dipilih. " +
        "Sajikan dalam format yang sangat terstruktur, profesional, dan menggunakan bahasa klinis yang presisi.";
}


else if(type == "acp") {
    prompt = base + 
        "Bertindaklah sebagai spesialis perawatan paliatif dan konselor ACP (Advance Care Planning). " +
        "Buatkan panduan master tentang ACP untuk topik: " + care + ". " +
        "Panduan harus mencakup: " +
        "1. Strategi Komunikasi: Teknik memulai percakapan ACP yang sensitif, empatik, dan efektif dengan pasien serta keluarga (termasuk cara mengatasi resistensi). " +
        "2. Elemen Legal & Medis: Komponen krusial yang wajib ada dalam dokumen legal ACP (seperti penunjukan kuasa asuhan, instruksi do-not-resuscitate, dan preferensi perawatan). " +
        "3. Tahapan Implementasi: Panduan langkah-demi-langkah dari diskusi awal hingga legalisasi dokumen. " +
        "4. Bank Soal (3 soal): Susun 3 studi kasus/soal pilihan ganda yang menguji pemahaman tentang etika, hukum, dan manajemen komunikasi dalam ACP. " +
        "5. Rasional: Sertakan kunci jawaban dan penjelasan mendalam untuk setiap soal agar saya dapat memahami logika pengambilan keputusan di balik setiap jawaban. " +
        "Sajikan dalam format yang sangat terstruktur, profesional, dan menggunakan pendekatan klinis yang etis.";
}






else if(type == "guide") {
    prompt = base + 
        "Bertindaklah sebagai konsultan ahli medis. Berikan panduan klinis (clinical guideline) yang paling komprehensif, paripurna, dan mutakhir untuk topik: " + care + ". " +
        "Struktur panduan harus mencakup: " +
        "1. Pendahuluan & Definisi: Dasar klinis dan urgensi penanganan untuk kondisi tersebut, " +
        "2. Protokol Penanganan Standar: Prosedur operasional langkah-demi-langkah, mulai dari asesmen awal, stabilisasi, hingga manajemen jangka panjang, " +
        "3. Algoritma Pengambilan Keputusan: Poin-poin kritis dalam menentukan tindakan medis berdasarkan kondisi pasien, " +
        "4. Checklist Keselamatan: Peringatan akan kontraindikasi dan risiko yang harus dihindari, " +
        "5. Bank Soal (3 soal): Buatlah 3 soal studi kasus yang menantang (pilihan ganda dan esai klinis) yang menguji pemahaman mendalam tentang panduan ini. " +
        "Sertakan kunci jawaban yang lengkap dengan rasional medis/ilmiah di setiap akhir soal. " +
        "Sajikan dalam format profesional, terstruktur dengan heading yang jelas, dan menggunakan bahasa klinis yang presisi.";
}

else if(type == "meds") {
    prompt = base + 
        "Bertindaklah sebagai ahli farmakologi paliatif. " +
        "1. Pilih secara acak satu gejala fisik (nyeri hebat, mual, atau konstipasi). " +
        "2. Buatkan panduan tata laksana komprehensif untuk gejala tersebut, mencakup: " +
        "   - Protokol pemilihan obat (pilihan pertama, kedua, dan adjuvan), " +
        "   - Pedoman dosis awal, rentang titrasi yang aman, serta cara pemantauan efek samping, " +
        "   - Prinsip 'nearing end of life' dalam pemberian obat. " +
        "3. Sajikan 3 Bank Soal (Pilihan Ganda dan Studi Kasus Klinis): Fokuskan pada pemilihan dosis, interaksi obat, dan manajemen gejala yang tepat. " +
        "4. Sertakan kunci jawaban beserta penjelasan rasional medis yang mendalam untuk setiap soal. " +
        "Pastikan jawaban Anda terstruktur, menggunakan terminologi medis yang akurat, dan merujuk pada pedoman paliatif internasional terkini. " +
        "Sajikan dalam format yang rapi dan mudah untuk dijadikan bahan referensi profesional.";
}


else if(type == "support") {
    prompt = base + 
        "Buatkan modul panduan komprehensif mengenai 'Teknik Komunikasi Empatik dan Dukungan Emosional bagi Keluarga Pasien " + care + "'. " +
        "Modul ini harus mencakup: " +
        "1. Prinsip Dasar Komunikasi Terapeutik: Teknik mendengarkan aktif, validasi perasaan, dan penyampaian berita buruk (breaking bad news) yang beretika, " +
        "2. Strategi Dukungan Emosional: Cara menghadapi berbagai fase kedukaan (grief) dan teknik menenangkan keluarga dalam kondisi krisis, " +
        "3. Contoh Dialog: Berikan 5 skenario dialog praktis yang bisa langsung diterapkan oleh tenaga medis, " +
        "4. Bank Soal (3 Pertanyaan): Susunlah 3 soal (pilihan ganda dan studi kasus esai) yang menguji pemahaman tentang komunikasi empatik, pengelolaan emosi keluarga, dan etika dukungan psikososial. Sertakan kunci jawaban dan penjelasan rasional untuk setiap soal. " +
        "Sajikan dalam format profesional, terstruktur dengan poin-poin yang jelas, dan menggunakan bahasa yang berempati serta inspiratif.";
}


else if(type == "case") {
    prompt = base + 
        "Bertindaklah sebagai instruktur klinis yang ahli dalam bidang " + care + ". " +
        "Tugas Anda adalah menyajikan modul latihan studi kasus yang paripurna. " +
        "Langkah-langkahnya: " +
        "1. Berikan 1 skenario kasus nyata yang kompleks dan menantang terkait " + care + ", " +
        "2. Setelah skenario tersebut, lampirkan 'Bank Soal Latihan' yang berisi 3 soal studi kasus tambahan (pilihan ganda dan esai klinis) yang mencakup berbagai aspek diagnosis, tindakan, dan etika, " +
        "3. Sertakan kunci jawaban beserta penjelasan rasional yang mendalam untuk setiap soal di bagian akhir (atau dalam format spoiler/tersembunyi agar saya bisa mencoba menjawabnya sendiri terlebih dahulu), " +
        "4. Gunakan standar medis/profesional terkini dalam penyusunan soal. " +
        "Tampilkan output dengan format yang rapi, terstruktur, dan mudah dibaca.";
}



else if(type == "infinite") {
    prompt = base + 
        "Aktifkan 'Mode INFINITE DRILL': Bertindaklah sebagai penguji ahli di bidang perawatan paliatif. " +
        "Tugas Anda: " +
        "1. Berikan 1 soal studi kasus kompleks secara acak dari topik: Emergency, Assessment, Guideline, Farmakologi, ACP, PPS v2, Dukungan Emosional, Terminal Care, atau Etika. " +
        "2. Setelah saya menjawab, berikan analisis mendalam: tentukan apakah jawaban saya benar/salah, jelaskan rasional medisnya dengan merujuk pada standar klinis terkini, dan koreksi jika ada pemahaman yang keliru. " +
        "3. Tanyakan apakah saya ingin melanjutkan ke soal berikutnya, atau berikan soal baru secara otomatis jika saya memberikan instruksi untuk lanjut. " +
        "4. Simpan catatan kecil tentang topik mana yang saya jawab dengan lemah, dan sesuaikan tingkat kesulitan soal berikutnya agar fokus pada area perbaikan tersebut (adaptif). " +
        "5. Mulailah sesi pertama sekarang dengan 1 soal studi kasus yang menantang beserta 4 pilihan jawaban (A, B, C, D). " +
        "Gunakan gaya bahasa yang profesional, suportif, dan edukatif.";
}


else if(type == "terminal") {
    prompt = base + 
        "Bertindaklah sebagai ahli perawatan paliatif. Berikan panduan 'Terminal Hour Care' (perawatan di jam-jam terakhir kehidupan) yang sangat komprehensif, mendalam, dan paripurna. " +
        "Panduan harus mencakup: " +
        "1. Manajemen Gejala Fisik: Penjelasan mendalam dan protokol penanganan gejala seperti death rattle, dispnea (sesak napas), nyeri, kegelisahan terminal, dan perawatan mulut/kulit, " +
        "2. Pendekatan Spiritual & Psikososial: Strategi memberikan dukungan bagi pasien dan pendampingan bagi keluarga yang berduka, " +
        "3. Etika & Komunikasi: Cara berkomunikasi dengan keluarga di saat kritis, " +
        "4. Bank Soal (3 Pertanyaan): Buatlah 3 soal studi kasus pilihan ganda dan esai yang komprehensif mengenai skenario klinis, manajemen gejala, dan dilema etis dalam 'Terminal Hour Care'. Sertakan kunci jawaban beserta penjelasan rasionalnya untuk setiap soal. " +
        "Sajikan seluruh materi dalam format yang terstruktur, menggunakan bahasa profesional yang berempati, dan sesuai dengan standar medis paliatif terkini.";
}





else if(type == "ethics") {
    prompt = base + 
        "Buatkan panduan komprehensif mengenai dilema etis yang sering terjadi dalam profesi atau bidang " + care + ". " +
        "Panduan ini harus mencakup: " +
        "1. Penjelasan mendalam mengenai 5 dilema etis yang paling umum, " +
        "2. Framework atau langkah-langkah sistematis dalam mengambil keputusan yang bijak dan beretika, " +
        "3. Analisis pro dan kontra dari setiap dilema, " +
        "4. Sediakan 3 bank soal studi kasus dilema etis yang bervariasi (lengkap dengan pilihan jawaban atau panduan diskusinya) untuk tujuan pelatihan atau refleksi. " +
        "Sajikan jawaban dalam format yang terstruktur, profesional, dan mudah dipahami.";
}





                        navigator.clipboard.writeText(prompt).then(function() {
                            status.style.color = "#059669";
                            status.innerHTML = "Instruksi disalin!Silakan paste di Gemini.";
                            setTimeout(function() { 
                                status.style.color = "#475569";
                                status.innerHTML = "Silakan pilih modul,klik tombol di bawah ini untuk copy-paste di Gemini."; 
                            }, 10000);
                            window.open('https://gemini.google.com/', '_blank');
                        });
                    }
